import * as React from 'react';
import * as jsxRuntime from 'react/jsx-runtime';
import * as ReactDOM from 'react-dom';
import * as sonner from 'sonner';

// The module objects plugin client entries share with the host (design.md §5.7). The forwarding
// modules and import map that reach them are generated by `scripts/shared-modules.mjs`, which
// lists the same specifiers.

const uiComponents = import.meta.glob<Record<string, unknown>>(
    '../../../../../packages/ui/src/components/**/*.tsx',
    { eager: true }
);
const uiLib = import.meta.glob<Record<string, unknown>>(
    '../../../../../packages/ui/src/lib/utils.ts',
    {
        eager: true,
    }
);

declare global {
    var __whimShared: Readonly<Record<string, unknown>> | undefined;
}

/** Publish the shared modules before any plugin client entry loads. */
export function publishSharedModules(): void {
    const shared: Record<string, unknown> = {
        react: React,
        'react/jsx-runtime': jsxRuntime,
        'react-dom': ReactDOM,
        sonner,
    };
    for (const [path, module] of Object.entries({ ...uiComponents, ...uiLib })) {
        const specifier = path
            .replace(/^.*\/packages\/ui\/src\//, '@whimkit/ui/')
            .replace(/\.tsx?$/, '');
        shared[specifier] = module;
    }
    globalThis.__whimShared = shared;
}
